import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit

root = Path('products/distribution/nonprofit-spreadsheet-paid-call')
raw = (root / 'nrc-tenders.html').read_bytes()
base = 'https://www.nrc.no/tenders'
expected_hash = '8a77082f1874007d50d0ee2704941a394557bab2e5a3ad674b766be296f33784'
actual_hash = hashlib.sha256(raw).hexdigest()
if actual_hash != expected_hash:
    raise SystemExit('Saved NRC page differs from the confirmed FETCH receipt')

class Links(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links = []
        self.current = None

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            self.current = [dict(attrs).get('href') or '', []]

    def handle_data(self, data):
        if self.current is not None:
            self.current[1].append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.current is not None:
            href, parts = self.current
            self.links.append((urljoin(base, href), ' '.join(' '.join(parts).split())))
            self.current = None

parser = Links()
parser.feed(raw.decode('utf-8', errors='replace'))
terms = re.compile(r'\b(spreadsheet|excel|csv|data quality|data validation|data clean(?:ing|up)|data verification|reporting data)\b', re.I)
matches = {}
for url, label in parser.links:
    parsed = urlsplit(url)
    if parsed.scheme == 'https' and parsed.hostname in {'www.nrc.no', 'nrc.no'} and label and terms.search(label + ' ' + parsed.path.replace('-', ' ')):
        matches.setdefault(url, label)
result = {'source': base, 'fetch_receipt': 'TASK-179516556100', 'sha256': actual_hash, 'anchors_examined': len(parser.links), 'total_matching_urls': len(matches), 'first_15_matching_links': [{'url': url, 'label': label} for url, label in list(matches.items())[:15]], 'coverage': 'Saved first-party anchor text and URL paths only. This does not check unlinked notices, notice bodies, deadlines, compensation or eligibility.'}
output = root / 'nrc-first-party-qa-links.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
